  ["Know what it is worth"] = "Savoir ce que ça vaut",
  ["Look"] = "Apparence",
  ["Look something up"] = "Chercher quelque chose",
  ["Needs %s."] = "Nécessite %s.",
  ["One key clears the screen for the view"] = "Une touche dégage l'écran pour la vue",
  ["One key hides the interface but the action bars."] = "Une touche masque l'interface sauf les barres d'action.", -- luacheck: ignore 631
  ["Or switch everything on"] = "Ou tout activer",
  ["Pins on the minimap"] = "Repères sur la minicarte",
  ["Prices, and who of your characters has what"] = "Les prix, et lequel de vos personnages a quoi",
  ["Quest givers' words around the Orbiter, your answers as symbols."] = "Les paroles des donneurs de quêtes autour de l'Orbiter, vos réponses en symboles.", -- luacheck: ignore 631
  ["Rings of your emotes, lines and macros on one key; a thank-you when someone buffs or resurrects you; a bow or a polite no to a duel or a trade."] = "Des anneaux de vos emotes, phrases et macros sur une touche ; un merci quand on vous améliore ou vous ressuscite ; une révérence ou un non poli à un duel ou un échange.", -- luacheck: ignore 631
  ["Roleplay with Bastian's"] = "Jeu de rôle avec Bastian's",
  ["Route steps"] = "Étapes de l'itinéraire",
  ["Route there on anything: road, flight, boat."] = "Un itinéraire vers n'importe quoi : route, vol, bateau.", -- luacheck: ignore 631
  ["Show the welcome at every login"] = "Afficher l'accueil à chaque connexion",
  ["Sit by a fire together, share it with your group, a camp ring for the evening."] = "S'asseoir ensemble près d'un feu, le partager avec votre groupe, un anneau de camp pour la soirée.", -- luacheck: ignore 631
  ["Switch on %s on the Suite page."] = "Activez %s sur la page Suite.",
  ["Talk to a quest giver with the conversation on"] = "Parler à un donneur de quêtes avec la conversation activée", -- luacheck: ignore 631
  ["Talk to people without quest windows"] = "Parler aux gens sans fenêtres de quête",
  ["Text"] = "Texte",
  ["The Gestures ring"] = "L'anneau des Gestes",
  ["The Orbiter"] = "L'Orbiter",
  ["The Orbiter plays Spoken's voices for quests, places, books and bosses, and the game's voice where Spoken has none."] = "L'Orbiter joue les voix de Spoken pour les quêtes, les lieux, les livres et les boss, et la voix du jeu là où Spoken n'en a pas.", -- luacheck: ignore 631
  ["The Orbiter plays the zone's story."] = "L'Orbiter joue l'histoire de la zone.",
  ["The campfire"] = "Le feu de camp",
  ["The hub: every app's settings, the Suite page, Help."] = "Le hub : les réglages de chaque application, la page Suite, l'aide.", -- luacheck: ignore 631
  ["The land speaks"] = "La terre parle",
  ["The land tells its stories as you walk (the Orbiter with Spoken)"] = "La terre raconte ses histoires pendant que vous marchez (l'Orbiter avec Spoken)", -- luacheck: ignore 631
  ["The screen for the view"] = "L'écran pour la vue",
  ["The search opens a page for anything."] = "La recherche ouvre une page pour n'importe quoi.",
  ["The suite's button at the minimap"] = "Le bouton de la suite sur la minicarte",
  ["The suite's words"] = "Les mots de la suite",
  ["The way there, by road, flight and boat"] = "Le chemin, par la route, les airs et le bateau",
  ["The welcome stays away at login; the General page brings it back."] = "L'accueil ne s'affiche plus à la connexion ; la page Général le fait revenir.", -- luacheck: ignore 631
  ["The welcome window at every login, until Don't show again in its corner (plan-launch-version D)."] = "La fenêtre d'accueil à chaque connexion, jusqu'à Ne plus afficher dans son coin (plan-launch-version D).", -- luacheck: ignore 631
  ["Try it"] = "Essayer",
  ["What matters for this way"] = "Ce qui compte pour cette voie",
  ["What you get"] = "Ce que vous obtenez",
  ["Where things are"] = "Où sont les choses",
  ["You know the way."] = "Vous connaissez le chemin.",
  ["Your first five minutes"] = "Vos cinq premières minutes",
  ["Your gestures on a ring, thanks in your own words"] = "Vos gestes sur un anneau, des remerciements avec vos mots", -- luacheck: ignore 631
  ["Your pack"] = "Votre paquetage",
  -- the welcome's information layer (02.11.2026)
  ["Highpeak"] = "Haut-Pic",
  ["Greenback Ridge"] = "Crête du Dos-Vert",
  ["Peacebloom"] = "Pacifique",
  ["%d yd high, %d yd away"] = "%d m de haut, à %d m",
  ["%d yd away"] = "à %d m",
  -- the artist's credit under a hand-drawn dungeon map (ADR 0048, 02.11.2026)
  ["Map by %s"] = "Carte de %s",
  ["Map by %s (%s), used with kind permission. Thank you!"] = "Carte de %s (%s), utilisée avec son aimable autorisation. Merci !",
  ["Click, then Ctrl+C to copy the address"] = "Cliquez, puis Ctrl+C pour copier l'adresse",
  -- the minimap buttons
  ["Welcome"] = "Bienvenue",
  ["Its own minimap button for the welcome"] = "Son propre bouton de minicarte pour l'accueil",
  ["A button at the minimap that shows the welcome with the Wanderer and the Scholar again."] = "Un bouton sur la minicarte qui montre à nouveau l'accueil avec le Vagabond et l'Érudit.",
  ["%s is switched off. Its page has the switch to turn it on."] = "%s est désactivé. Sa page a l'interrupteur pour l'activer.",
  ["Click: its page, to switch it on."] = "Clic : sa page, pour l'activer.",

  -- What's new (ADR 0021, LG5): the release notes, keyed by their English text
  ["The map no longer sends you to quest givers who are not there or have nothing to give: world event quests wait for their event, quests that are not in the game are gone, and a giver who does not list a quest loses its pin until you gain a level."] = "La carte ne vous envoie plus vers des donneurs de quêtes absents ou sans rien à donner : les quêtes d'événement mondial attendent leur événement, les quêtes absentes du jeu disparaissent, et un donneur qui ne liste pas une quête perd son repère jusqu'à ce que vous gagniez un niveau.",
  ['Quests far below your level stay on the map in grey, marked "Low level".'] = 'Les quêtes bien en dessous de votre niveau restent sur la carte en gris, marquées "Niveau bas".',
  ["The gold stories' map scales smoothly with its window, which takes the map's shape; tokens light up under the cursor; the book opens on the map."] = "La carte des histoires d'or s'adapte en douceur à sa fenêtre, qui prend la forme de la carte ; les jetons s'allument sous le curseur ; le livre s'ouvre sur la carte.",
  ["Zone level ranges on the map are coloured for your character's level."] = "Les plages de niveaux des zones sur la carte sont colorées selon le niveau de votre personnage.",
  ['A dungeon in a list says "in 4 levels" while it is still ahead of you.'] = 'Un donjon dans une liste indique "dans 4 niveaux" tant qu\'il est encore devant vous.',
  ["A zone's page says the fishing skill it asks for."] = "La page d'une zone indique la compétence de pêche qu'elle demande.",
  ["The map's footer shows the travel time to the point under your cursor."] = "Le pied de la carte affiche le temps de trajet jusqu'au point sous votre curseur.",
  ["Items whose cheapest listing is far under their 30-day median are marked as a bargain."] = "Les objets dont l'offre la moins chère est bien en dessous de leur médiane sur 30 jours sont marqués comme une bonne affaire.",
  ["A small bar shows the time left on a flight whose duration you flew before."] = "Une petite barre affiche le temps restant d'un vol que vous avez déjà effectué.",
  ["Dungeon pages list the quests whose targets live inside, from the Classic data, for 16 more dungeons and raids."] = "Les pages de donjon listent les quêtes dont les cibles s'y trouvent, d'après les données Classic, pour 16 donjons et raids de plus.",
  ['A "Class quests" view lists your class\'s quests by status and level.'] = 'Une vue "Quêtes de classe" liste les quêtes de votre classe par statut et par niveau.',
  ["Targeting or mousing over a rare creature shows its name with a Map button."] = "Cibler une créature rare ou la survoler affiche son nom avec un bouton Carte.",
  ["A route says in one word whether the way is safe, needs care or is risky for your level."] = "Un itinéraire indique en un mot si le chemin est sûr, demande de la prudence ou est risqué pour votre niveau.",
  ['"Craft for gold" lists the recipes you know by profit, with the best way to sell each product.'] = '"Fabriquer pour de l\'or" liste les recettes que vous connaissez par profit, avec la meilleure façon de vendre chaque produit.',
  ['A "Trainer" view lists the spells your class trainers teach you now, with cost and the nearest trainer.'] = 'Une vue "Entraîneur" liste les sorts que vos entraîneurs de classe vous enseignent maintenant, avec le coût et l\'entraîneur le plus proche.',
  ["Your character's page names the gold to save for: the next training, riding and a mount."] = "La page de votre personnage indique l'or à mettre de côté : le prochain entraînement, la monte et une monture.",
  ["A dungeon's page lists your characters' runs and lockouts."] = "La page d'un donjon liste les passages et les verrouillages de vos personnages.",
  ["A farm spot's page shows your own gold per hour there after twenty kills, beside the guide's figure."] = "La page d'un lieu de farm affiche, après vingt ennemis tués, votre propre or par heure à cet endroit, à côté du chiffre du guide.",
  ["The Atlas has a rail of seven sections with tabs instead of a bar of nineteen buttons."] = "L'Atlas a un rail de sept sections avec des onglets au lieu d'une barre de dix-neuf boutons.",
  ["The Atlas's search stands in the title bar, always at hand."] = "La recherche de l'Atlas se trouve dans la barre de titre, toujours à portée de main.",
  ["The Atlas's lists come in pages that fit the window instead of a scroll."] = "Les listes de l'Atlas se présentent en pages adaptées à la fenêtre au lieu d'un défilement.",
  ["Stat tiles on Here, Gold and Characters; a dungeon's and a character's page read in tabs."] = "Des vignettes de statistiques sur Ici, Gold et Personnages ; la page d'un donjon et celle d'un personnage se lisent en onglets.",
  ["Gold's Bags tab gives one answer per bag item with the reason."] = "L'onglet Sacs de Gold donne une réponse par objet de sac avec la raison.",
  ["The settings hub reads as a rail of apps with their one-line purpose and every option on a card."] = "Le centre des paramètres se présente comme un rail d'apps avec leur but en une ligne et chaque option sur une carte.",
  ['Share the walks, flight times and ride waits your game learned through "Copy my captures" in the settings.'] = 'Partagez les trajets à pied, les temps de vol et les attentes de transport que votre jeu a appris via "Copier mes relevés" dans les paramètres.',
  ["Dragging a window no longer jumps it over the top of the screen, and Dock works again after the docked Browser was closed by hand."] = "Faire glisser une fenêtre ne la fait plus sauter au-delà du haut de l'écran, et l'ancrage refonctionne après la fermeture manuelle du Navigateur ancré.",
  ["In a narrow Browser window a click on a view's row now shows the page it opens."] = "Dans une fenêtre étroite du Navigateur, un clic sur la ligne d'une vue affiche maintenant la page qu'elle ouvre.",
  ["The Browser's search always looks in every list; the list's own filter narrows the list."] = "La recherche du Navigateur cherche toujours dans toutes les listes ; le filtre propre à la liste restreint la liste.",
  ["The physical map no longer shows a stray strip of old parchment west of Kalimdor."] = "La carte physique n'affiche plus de bande errante de vieux parchemin à l'ouest de Kalimdor.",
  ["The level band under a zone's name on the map reads clearly in every difficulty colour."] = "La plage de niveaux sous le nom d'une zone sur la carte se lit clairement dans chaque couleur de difficulté.",
  ["A farm spot without a known gold rate says so once, and the text is no longer cut off."] = "Un lieu de farm sans taux d'or connu le dit une seule fois, et le texte n'est plus coupé.",
  ["A quest's sheet under the mouse on a chain's step shows over the Browser instead of behind it."] = "La feuille d'une quête sous la souris sur une étape de chaîne s'affiche au-dessus du Navigateur au lieu de derrière.",
  ["The people on a quest's sheet show their faces again."] = "Les personnages sur la feuille d'une quête montrent de nouveau leur visage.",
  ['The map\'s right-click menu no longer lists "Show on map" twice.'] = 'Le menu du clic droit de la carte ne liste plus "Afficher sur la carte" en double.',
  ["A click on a class quest no longer empties the Class quests list while it is rebuilt."] = "Un clic sur une quête de classe ne vide plus la liste Quêtes de classe pendant sa reconstruction.",
  ['A dungeon one level away now says "in 1 level".'] = 'Un donjon à un niveau de distance indique maintenant "dans 1 niveau".',
  ["The gold book's text follows the suite's text size and uses three font sizes instead of seven."] = "Le texte du livre de l'or suit la taille de texte de la suite et utilise trois tailles de police au lieu de sept.",
  ["The gold book's maps and the story map's marks open their place on the world map."] = "Les cartes du livre de l'or et les marques de la carte des histoires ouvrent leur emplacement sur la carte du monde.",
  ["The names in the gold book's pages are links: hover for the tooltip, click to open."] = "Les noms dans les pages du livre de l'or sont des liens : survolez pour l'infobulle, cliquez pour ouvrir.",
  ["A page in the Browser has its own filter: type to narrow every list on it."] = "Une page du Navigateur a son propre filtre : tapez pour restreindre chaque liste qu'elle contient.",
  ["The Browser's sections and tabs are coloured symbols with text instead of green buttons."] = "Les sections et onglets du Navigateur sont des symboles colorés avec du texte au lieu de boutons verts.",
  ["/balts opens your characters in the Browser: the list on the left, a character's tabs on the right."] = "/balts ouvre vos personnages dans le Navigateur : la liste à gauche, les onglets d'un personnage à droite.",
  ["Gold's new Bargains tab lists the items selling far under their usual price."] = "Le nouvel onglet Bonnes affaires de Gold liste les objets vendus bien en dessous de leur prix habituel.",
  ["The Gold Stories list shows each story as a tile with Bastian's picture and its first words."] = "La liste des Histoires d'or montre chaque histoire sous forme de vignette avec l'image de Bastian et ses premiers mots.",
  ["The map keeps you centred by default; looking around pauses it until the map closes, and only the Centred button switches it off."] = "La carte vous garde centré par défaut ; regarder autour la met en pause jusqu'à la fermeture de la carte, et seul le bouton Centré la désactive.",
  ["The minimap shows only the herbs and ore the game's tracking really finds, not every known spawn."] = "La minicarte n'affiche que les herbes et minerais que le pistage du jeu trouve réellement, et non chaque point d'apparition connu.",
  ["A window you open always comes to the front, also one that was already open behind another."] = "Une fenêtre que vous ouvrez passe toujours au premier plan, même une fenêtre déjà ouverte derrière une autre.",
  ["The campfire flame can be dragged anywhere and remembers its place."] = "La flamme du feu de camp peut être déplacée n'importe où et se souvient de sa place.",
  ["Hovering a quest reward in the Orbiter shows the item's full stats."] = "Survoler une récompense de quête dans l'Orbiter affiche les statistiques complètes de l'objet.",
  ["My quests lists every objective of a quest with its count, not just the first open one."] = "Mes quêtes liste chaque objectif d'une quête avec son compte, et pas seulement le premier encore ouvert.",
  ["A route starts on your side of a ridge instead of across a mountain."] = "Un itinéraire commence de votre côté d'une crête au lieu de traverser une montagne.",
  ["After you die, Bastian's Route drops the old arrow and guides you on foot back to your corpse, marked clearly on the map."] = "Après votre mort, Bastian's Route abandonne l'ancienne flèche et vous guide à pied jusqu'à votre cadavre, clairement marqué sur la carte.",
  ["/way now works without TomTom and starts a route; several lines become one route, and a button chooses a new route or adding to the current one."] = "/way fonctionne maintenant sans TomTom et lance un itinéraire ; plusieurs lignes forment un seul itinéraire, et un bouton permet de choisir entre un nouvel itinéraire et l'ajout à l'itinéraire actuel.",
  ["The map shows only the quest targets you still need, each labelled with what to do there and how many are left."] = "La carte n'affiche que les cibles de quête dont vous avez encore besoin, chacune étiquetée avec ce qu'il faut y faire et le nombre restant.",
  ["The minimap follows your character even when the game reports no movement, on boats, after a knockback or a teleport."] = "La minicarte suit votre personnage même quand le jeu ne signale aucun mouvement : sur les bateaux, après un repoussement ou une téléportation.",
  ["Switching a layer off also clears its pins from the minimap."] = "Désactiver une couche retire aussi ses repères de la minicarte.",
  ["Creatures found by hunter, druid, paladin and warlock tracking now show on Bastian's map styles."] = "Les créatures trouvées par le pistage du chasseur, du druide, du paladin et du démoniste s'affichent maintenant dans les styles de carte de Bastian's.",
  ["Bastian's Courtesy is now an addon of its own: when someone helps you, a small ring offers a fitting thank-you, and your click says it in character."] = "Bastian's Courtesy est maintenant un addon à part entière : quand quelqu'un vous aide, un petit anneau propose un remerciement adapté, et votre clic le dit dans le rôle de votre personnage.",
  ["The gesture ring stays open until you press its key again."] = "L'anneau des gestes reste ouvert jusqu'à ce que vous appuyiez de nouveau sur sa touche.",
  ["Routes inside Stormwind no longer detour around the harbour to reach a street nearby."] = "Les itinéraires dans Stormwind ne font plus un détour par le port pour atteindre une rue proche.",
  ["Trainers and vendors say what kind they are, also when their title has no word Trainer in it."] = "Les entraîneurs et les marchands indiquent de quel type ils sont, même quand leur titre ne contient pas le mot Entraîneur.",
  ["The campfire card is now a stylized flame you click: sit down, share or hide."] = "La carte du feu de camp est maintenant une flamme stylisée sur laquelle on clique : s'asseoir, partager ou masquer.",
  ["A new minimap button lights a kit you carry, and the foot icon offers what you can add to a fire, Violet Dust included."] = "Un nouveau bouton de minicarte allume un kit que vous portez, et l'icône du pied propose ce que vous pouvez ajouter à un feu, Violet Dust compris.",
  ["Send to writes a character's name with its surname, so the mail reaches them on Forever."] = "Envoyer à écrit le nom d'un personnage avec son nom de famille, pour que le courrier lui parvienne sur Forever.",
  ["Alts can forget a character you deleted, and its filter now finds class, race, place and every item held."] = "Alts peut oublier un personnage que vous avez supprimé, et son filtre trouve maintenant la classe, la race, le lieu et chaque objet détenu.",
  ["A new key in Key Bindings opens whatever is under your mouse in the Browser."] = "Une nouvelle touche dans les raccourcis clavier ouvre dans le Navigateur ce qui se trouve sous votre souris.",
  ["The quest window has a Route to the giver button."] = "La fenêtre de quête a un bouton Itinéraire vers le donneur.",
  ["A quest item you already hold no longer keeps its pin where it lay."] = "Un objet de quête que vous possédez déjà ne garde plus son repère là où il se trouvait.",
  ["The chat's copy window has a scroll bar."] = "La fenêtre de copie du chat a une barre de défilement.",
  ["The chat input bar no longer disappears behind the window, and a reload no longer takes the keyboard."] = "La barre de saisie du chat ne disparaît plus derrière la fenêtre, et un rechargement ne vous prive plus du clavier.",
  ["Quests now wait for the quest players were seen to need first, where that cannot lock them out."] = "Les quêtes attendent maintenant la quête dont on a vu que les joueurs avaient d'abord besoin, là où cela ne peut pas les bloquer.",
  ['The Browser\'s search no longer stays on "Searching ..." while other things happen; a search that fails says so.'] = 'La recherche du Browser ne reste plus sur "Recherche en cours ..." quand autre chose se passe ; une recherche qui échoue le dit.',
  ["Bastian's Route now has the walk network of both continents: routes follow roads, passes and bridges instead of the straight line."] = "Bastian's Route dispose maintenant du réseau de chemins des deux continents : les itinéraires suivent les routes, les cols et les ponts au lieu de la ligne droite.",
  ["The herbs and ore the game tracks no longer vanish from Bastian's minimap styles with a map layer, the pin limit or the layers-on-the-minimap setting; they show as yellow pins of their own."] = "Les herbes et minerais que le jeu piste ne disparaissent plus des styles de la minicarte de Bastian à cause d'une couche de carte, de la limite de repères ou du réglage des couches sur la minicarte ; ils s'affichent comme des repères jaunes à part.",
  ["Gold finds the market prices on the live EU RP realm."] = "Gold trouve les prix du marché sur le royaume RP EU en production.",
  ["Herbs and ore on Bastian's minimap styles now sit exactly where the game's own dots are."] = "Les herbes et minerais sur les styles de la minicarte de Bastian se trouvent désormais exactement là où sont les points du jeu.",
  ["Hovering a quest lights its whole block in one colour and the row under the mouse in another, so chain quests no longer look like quests of their own."] = "Quand vous survolez une quête, tout son bloc s'éclaire d'une couleur et la ligne sous la souris d'une autre, si bien que les chaînes de quêtes ne ressemblent plus à des quêtes isolées.",
  ["Quests now say what to do first: the task sits right under the quest in My quests and opens the quest page, with the story last."] = "Les quêtes disent maintenant d'abord ce qu'il faut faire : la tâche se trouve juste sous la quête dans Mes quêtes et ouvre la page de la quête, l'histoire vient en dernier.",
  ['Objectives show their count once, a quest with one objective counts its items, and "worth unknown" no longer fills a line.'] = "Les objectifs n'affichent leur nombre qu'une fois, une quête à un seul objectif compte ses objets, et 'valeur inconnue' ne remplit plus une ligne.",
  ["Bastian's minimap styles show only the herbs and ore your tracking finds, no more stray pins on you or on quest marks."] = "Les styles de la minicarte de Bastian n'affichent plus que les herbes et minerais que votre pistage trouve, fini les repères parasites sur vous ou sur les marques de quête.",
  ["Quests now open on a parchment sheet with the task first, the story and large rewards, from My quests, the map and on hover at the Orbiter's quest marks."] = "Les quêtes s'ouvrent maintenant sur une feuille de parchemin avec la tâche en premier, l'histoire et de grandes récompenses : depuis Mes quêtes, depuis la carte et au survol des marques de quête de l'Orbiter.",
  ["Rewards come from the game itself, so quests no source knows show their real experience, money and items."] = "Les récompenses viennent du jeu lui-même, si bien que les quêtes qu'aucune source ne connaît affichent leur véritable expérience, leur argent et leurs objets.",
  ["My quests shows each quest on two lines, a finished quest has its own mark and says who takes it, and the voice and chain buttons stay on the row."] = "Mes quêtes affiche chaque quête sur deux lignes, une quête terminée a sa propre marque et dit qui la prend, et les boutons de voix et de chaîne restent sur la ligne.",
  ["The chain symbol shows a quest chain as a trail with every step, what it needs and what is still ahead."] = "Le symbole de chaîne montre une chaîne de quêtes comme un sentier avec chaque étape, ce qu'elle demande et ce qui reste à faire.",
  ["The map shows the targets of one quest, the focused or the nearest, and finished quests' hand-ins as large signs."] = "La carte montre les cibles d'une seule quête, celle en focus ou la plus proche, et les lieux de remise des quêtes terminées sous forme de grands signes.",
  ["A second click on a quest closes its sheet, and the sheet shows the quest giver and the target in 3D."] = "Un second clic sur une quête ferme sa feuille, et la feuille montre le donneur de quêtes et la cible en 3D.",
  ["Show on map opens at the nearest group of a quest's targets, not between two far camps."] = "Montrer sur la carte s'ouvre sur le groupe de cibles le plus proche d'une quête, et non entre deux camps éloignés.",
  ["Auctioneers, stable masters, innkeepers, bankers, flight masters and battlemasters are marked as what they are, and several hundred more vendors and repairers are found."] = "Les commissaires-priseurs, maîtres des écuries, aubergistes, banquiers, maîtres de vol et maîtres de guerre sont marqués pour ce qu'ils sont, et plusieurs centaines de marchands et de réparateurs de plus sont trouvés.",
  ["A page in the Browser reads like the quest sheet: the figure large at the left on a wide window, the name and what matters first, the main buttons with the rest under More, and chapters in one column instead of a grid of blocks."] = "Une page du Navigateur se lit comme la feuille de quête : l'image en grand à gauche dans une fenêtre large, le nom et l'essentiel d'abord, les boutons principaux avec le reste sous Plus, et les chapitres en une seule colonne au lieu d'une grille de blocs.",
  ['Pages are sorted into chapters in a fixed reading order: a zone\'s quests under one heading, an item under "Where to get it", "What it is for", "Worth" and "Yours", a monster\'s drops first.'] = "Les pages sont classées en chapitres dans un ordre de lecture fixe : les quêtes d'une zone sous un seul titre, un objet sous 'Où l'obtenir', 'À quoi il sert', 'Valeur' et 'À vous', et pour un monstre, ses butins d'abord.",
  ["A page in the Browser is drawn on parchment like the quest sheet, its rows are calm (two lines, icons only under the mouse), and a zone's quest groups you cannot act on yet are folded until clicked."] = "Une page du Navigateur est dessinée sur parchemin comme la feuille de quête, ses lignes sont calmes (deux lignes, icônes seulement sous la souris), et les groupes de quêtes d'une zone sur lesquels vous ne pouvez pas encore agir sont repliés jusqu'au clic.",
  ["A zone's page lists its people by what they do, vendors, trainers, zones and dungeons say in one sentence what they are, quests far above your level no longer lead \"To do here\", and pages on parchment keep the paper's colours under the mouse and switch without a reload."] = "La page d'une zone liste ses habitants selon ce qu'ils font, les marchands, entraîneurs, zones et donjons disent en une phrase ce qu'ils sont, les quêtes bien au-dessus de votre niveau n'ouvrent plus 'À faire ici', et les pages sur parchemin gardent les couleurs du papier sous la souris et changent sans rechargement.",
  ["Stormwind's bankers, guards, mailboxes and other people and objects inside the city are listed and shown in Stormwind City, no longer in Elwynn Forest."] = "Les banquiers, gardes, boîtes aux lettres et autres personnages et objets de Stormwind situés dans la ville sont listés et affichés dans Stormwind City, et plus dans Elwynn Forest.",
  ["Test and placeholder records of the game's data (unused NPCs, invisible triggers, deprecated and test items, the weapons monsters hold) no longer show in lists, zone pages and the search."] = "Les enregistrements de test et de substitution des données du jeu (PNJ inutilisés, déclencheurs invisibles, objets obsolètes et de test, les armes que tiennent les monstres) n'apparaissent plus dans les listes, les pages de zone et la recherche.",
  ['"To do here" ranks a quest by the experience it really gives where the game data names it, no longer by an estimate from its level.'] = "'À faire ici' classe une quête selon l'expérience qu'elle donne réellement là où les données du jeu la donnent, et non plus selon une estimation tirée de son niveau.",
  ["Pages on parchment keep readable colours everywhere, a place's mini map opens the large map there, a dungeon's floor map no longer sticks to other pages, the quest sheet opens on the free side of the Orbiter, and a locked Orbiter says that it is locked."] = "Les pages sur parchemin gardent partout des couleurs lisibles, la minicarte d'un lieu ouvre la grande carte à cet endroit, la carte d'étage d'un donjon ne reste plus collée aux autres pages, la feuille de quête s'ouvre du côté libre de l'Orbiter, et un Orbiter verrouillé indique qu'il est verrouillé.",
  ["The Browser's navigation is a bar of category buttons on top, and the list always stands beside the page as two tiles; a narrow or docked window shows one of them at a time."] = "La navigation du Navigateur est une barre de boutons de catégorie en haut, et la liste se trouve toujours à côté de la page sous forme de deux vignettes ; une fenêtre étroite ou ancrée n'en montre qu'une à la fois.",
  ["The Browser's lists and search results are tiles: a picture, the name and a line that says what it is."] = "Les listes et résultats de recherche du Navigateur sont des vignettes : une image, le nom et une ligne qui dit ce que c'est.",
  ["Browser lists show each thing as a tile with its own facts: a quest's state, giver, level and chain step, a monster's level and rank, a zone's level band."] = "Les listes du Navigateur montrent chaque élément sous forme de vignette avec ses propres informations : pour une quête son état, son donneur, son niveau et son étape de chaîne, pour un monstre son niveau et son rang, pour une zone sa tranche de niveaux.",
  ["The Orbiter has a small lock under its play button: click it to lock the ring in place or to move it freely."] = "L'Orbiter a un petit verrou sous son bouton de lecture : un clic le verrouille en place ou le laisse se déplacer librement.",
  ["The Browser's Slim mode is gone; the quest tracker frame (/bq tracker) is the tracker, and a Browser left in slim mode opens wide again."] = "Le mode Slim du Navigateur a disparu ; le cadre de suivi des quêtes (/bq tracker) est le suivi, et un Navigateur resté en mode Slim s'ouvre de nouveau en large.",
  ["The Browser's filters stand beside the search box, and a chip inside the box says where the list and the search look: your zone, your continent or everywhere."] = "Les filtres du Navigateur se trouvent à côté de la zone de recherche, et une pastille dans la zone indique où la liste et la recherche cherchent : votre zone, votre continent ou partout.",
  ["A page in the Browser shows its parts as cards: a zone's quests, people and monsters as tiles, four at a glance and the rest one click away, with nothing folded."] = "Une page du Navigateur montre ses parties sous forme de fiches : les quêtes, habitants et monstres d'une zone en vignettes, quatre d'un coup d'oeil et le reste à un clic, sans rien de replié.",
  ["A quest's page in the Browser is the same quest sheet as beside the Orbiter: the task first, the story, the rewards as tiles, with its people and its chain as cards below."] = "La page d'une quête dans le Navigateur est la même feuille de quête que près de l'Orbiter : la tâche d'abord, l'histoire, les récompenses en vignettes, avec ses habitants et sa chaîne en fiches en dessous.",
  ["A zone, a person or a dungeon in the Browser can be stepped into: a click on the edge of its tile shows its quests, people and monsters in the list, one group open at a time, while the page shows what you pick."] = "On peut entrer dans une zone, un personnage ou un donjon du Navigateur : un clic sur le bord de sa vignette montre ses quêtes, habitants et monstres dans la liste, un groupe ouvert à la fois, tandis que la page montre ce que vous choisissez.",
  ["A quest chain is a page of its own: the Quest chains list opens the chain with its steps in order, how far you are, the next step and the zones it leads through."] = "Une chaîne de quêtes est une page à part entière : la liste Chaînes de quêtes ouvre la chaîne avec ses étapes dans l'ordre, votre avancement, l'étape suivante et les zones qu'elle traverse.",
  ["A quest chain's page shows its way as coloured step tiles joined by arrows; the mouse on a step shows that quest's sheet and a click opens it."] = "La page d'une chaîne de quêtes montre son chemin sous forme de vignettes d'étapes colorées reliées par des flèches ; la souris sur une étape affiche la feuille de cette quête et un clic l'ouvre.",
  ["A quest in a chain shows its step, the chain and the steps before and after under its name; the chain button opens the chain's page instead of a window of its own."] = "Une quête d'une chaîne montre sous son nom son étape, la chaîne et les étapes avant et après ; le bouton de chaîne ouvre la page de la chaîne au lieu d'une fenêtre à part.",
  ["A zone's page lists the quest chains that pass through it, and the chain list is grouped by how far you are, with filters for progress, kind and length."] = "La page d'une zone liste les chaînes de quêtes qui la traversent, et la liste des chaînes est groupée selon votre avancement, avec des filtres de progression, de type et de longueur.",
  ["A chain's page shows its side quests under the step they follow, and the steps of other races and classes dashed."] = "La page d'une chaîne montre ses quêtes annexes sous l'étape qu'elles suivent, et les étapes d'autres races et classes en pointillés.",
  ["Follow on a quest chain's page tracks the step you are on and, after the hand-in, the next one by itself."] = "Suivre sur la page d'une chaîne de quêtes suit l'étape où vous en êtes et, après la remise, la suivante automatiquement.",
  ["The Browser's lists are named People, Monsters, Gathering and Chains, and a list with nothing in it shows no button."] = "Les listes du Navigateur s'appellent Habitants, Monstres, Récolte et Chaînes, et une liste vide n'affiche aucun bouton.",
  ["The coloured words on parchment pages and on the quest sheet are darker, so they read against the paper; a few colours on list tiles are a touch brighter."] = "Les mots colorés sur les pages en parchemin et sur la feuille de quête sont plus sombres, pour se lire sur le papier ; quelques couleurs des vignettes de liste sont un peu plus claires.",
  ["A double click on a tile in the Browser's list steps inside the thing, like the arrow at the tile's edge."] = "Un double clic sur une vignette de la liste du Navigateur entre dans l'élément, comme la flèche au bord de la vignette.",
  ["A thing's places show as a small map of each zone in your map style, with a dot for every place; a click opens the large map there."] = "Les lieux d'un élément s'affichent comme une petite carte de chaque zone dans votre style de carte, avec un point pour chaque lieu ; un clic ouvre la grande carte à cet endroit.",
  ["Zephras Isle no longer shows an empty map in the Blizzard, Modern, Pencil and Parchment styles."] = "Zephras Isle n'affiche plus de carte vide dans les styles Blizzard, Modern, Pencil et Parchment.",
  ["The zones Forever added now have their people, objects, quest hand-ins, objectives and objective texts, and the airships to Zephras Isle are on the routes."] = "Les zones ajoutées par Forever ont maintenant leurs habitants, objets, remises de quêtes, objectifs et textes d'objectifs, et les dirigeables vers Zephras Isle figurent dans les itinéraires.",
  ["A zone's tile shows the zone as a small map, and opening a part of a zone shows that part's people, monsters or quests as dots on the zone's map."] = "La vignette d'une zone montre la zone sous forme de petite carte, et ouvrir une partie d'une zone montre les habitants, monstres ou quêtes de cette partie sous forme de points sur la carte de la zone.",
  ["Forever's vendors show their stock, quests show the XP players measured and the rewards seen in Forever, and more Classic creatures have a place on the map."] = "Les marchands de Forever montrent leur stock, les quêtes montrent l'XP mesurée par les joueurs et les récompenses vues dans Forever, et davantage de créatures de Classic ont une place sur la carte.",
  ['The search no longer hangs on "Searching ..." while the quest texts are not loaded.'] = "La recherche ne reste plus bloquée sur 'Recherche ...' tant que les textes de quêtes ne sont pas chargés.",
  ["The Browser's lists open on everything instead of jumping to your zone, and most have a Zone filter."] = "Les listes du Navigateur s'ouvrent sur tout, au lieu de sauter à votre zone, et la plupart ont un filtre de zone.",
  ["The Browser has Gold Stories and All Notes in its top row, farm spots link to their story in the book, and a setting chooses the style of the mini maps."] = "Le Navigateur a les Histoires d'or et Toutes les notes dans sa rangée du haut, les lieux de farm renvoient à leur histoire dans le livre, et un réglage choisit le style des mini-cartes.",
  ["Routes now lead to the doors of the City of Dalaran, the Excavation Site in the Wetlands, the Ruins of Lordaeron and the Hall of Thanes."] = "Les itinéraires mènent maintenant aux portes de la ville de Dalaran, au Site de fouilles des Wetlands, aux Ruines de Lordaeron et à la Salle des Thanes.",
  ["Every Forever market now shows its own auction prices where they exist, and says which market a price comes from."] = "Chaque marché de Forever affiche désormais ses propres prix d'enchères là où il y en a, et indique de quel marché vient un prix.",
  ["The Browser's search groups its results by list and every category button says how many it found; mini maps show where you stand; a search typed inside a zone stays in that zone; item and recipe tiles say what they are; chains show on the map, route and list their rewards."] = "La recherche du Navigateur groupe ses résultats par liste, et chaque bouton de catégorie indique combien il en a trouvé ; les mini-cartes montrent où vous vous trouvez ; une recherche saisie dans une zone reste dans cette zone ; les vignettes d'objets et de recettes disent ce que c'est ; les chaînes apparaissent sur la carte, l'itinéraire et la liste avec leurs récompenses.",
  ["Stormwind on the Blizzard map style is the same city zoomed out and zoomed in, and the sea in the map styles no longer shows flat patches around the coasts."] = "Stormwind dans le style de carte Blizzard est la même ville en zoom arrière et en zoom avant, et la mer dans les styles de carte ne montre plus de taches plates autour des côtes.",
  ["Auction prices left over from the beta are now labelled as such."] = "Les prix d'enchères restés de la bêta sont désormais signalés comme tels.",
  ["Gold shows craft margins, disenchant value, whether a price is high or low in its range, a ledger of your sales and purchases, the market's best hours, and prices from AHledger, Auctionator or TSM when you have them."] = "Gold affiche les marges de fabrication, la valeur de désenchantement, si un prix est haut ou bas dans sa fourchette, un registre de vos ventes et achats, les meilleures heures du marché, et les prix d'AHledger, d'Auctionator ou de TSM si vous les avez.",
  ["Routes to Zephras Isle use Dalaran's skyboat, the skycutter at Skywatcher Plateau and, for the Alliance, the portal in Stormwind's Wizard's Sanctum."] = "Les itinéraires vers Zephras Isle utilisent le bateau céleste de Dalaran, le skycutter du Skywatcher Plateau et, pour l'Alliance, le portail du Sanctuaire des mages de Stormwind.",
  ["The gold stories no longer judge what they tell: the stamps, the verified and refuted labels and the status filter on farm spots are gone."] = "Les histoires d'or ne jugent plus ce qu'elles racontent : les tampons, les étiquettes vérifié et réfuté et le filtre de statut sur les lieux de farm ont disparu.",
  ["Bastian's Gold Adventures opens on a painted map of the world with every story as a picture with its level; a click opens the story, and the book stays one tab away."] = "Bastian's Gold Adventures s'ouvre sur une carte du monde peinte, chaque histoire sous forme d'image avec son niveau ; un clic ouvre l'histoire, et le livre reste à un onglet de distance.",
  ["Every gold story is open from the start."] = "Chaque histoire d'or est ouverte dès le départ.",
  ["The Rumour mill is now a plain list of what travellers are saying this week, one line each with who said it and the video, one click from the map."] = "Le Moulin à rumeurs est maintenant une simple liste de ce que disent les voyageurs cette semaine, une ligne chacun avec qui l'a dit et la vidéo, à un clic de la carte.",
  ["The stories' window is now called Bastian's Gold Adventures, and it has a new story: Wolf Flanks in Duskwood."] = "La fenêtre des histoires s'appelle maintenant Bastian's Gold Adventures et a une nouvelle histoire : Wolf Flanks in Duskwood.",
  ["Quests: right-click a quest in your log to abandon it; the game asks first."] = "Quêtes : clic droit sur une quête de votre journal pour l'abandonner ; le jeu demande confirmation.",
  ["Chat: the Up and Down keys recall your sent lines on Forever too (Alt+Up stays the game's)."] = "Chat : les flèches haut et bas rappellent vos lignes envoyées aussi sur Forever (Alt+Haut reste au jeu).",
  ["Orbiter: hovering a quest mark shows the quest's chain position and its rewards (money, reputation, items)."] = "Orbiter : survoler une marque de quête affiche sa position dans la chaîne et ses récompenses (argent, réputation, objets).",
  ["Quests: the zone view no longer errors on quests that are new in Forever."] = "Quêtes : la vue de zone ne provoque plus d'erreur sur les quêtes nouvelles dans Forever.",
  ["Core: no catalogue warning when a voice line starts or a quest reward loads."] = "Core : plus d'avertissement de catalogue quand une ligne vocale démarre ou qu'une récompense de quête se charge.",
  ["Bastian's minimap shows the herbs, ore and creatures your tracking finds on its own styles too, and the game's tracking button is back in its tools row."] = "La minicarte de Bastian montre aussi, dans ses propres styles, les plantes, minerais et créatures que ton pistage trouve, et le bouton de pistage du jeu est de retour dans sa barre d'outils.",
  ["The session plan (what fits into the next 30 to 180 minutes) moved from Route's Explore to Bastian's Gold and is off until you switch it on in Gold's settings."] = "Le plan de session (ce qui tient dans les 30 à 180 prochaines minutes) est passé de l'Exploration de Route à Bastian's Gold et reste désactivé jusqu'à ce que tu l'actives dans les réglages de Gold.",
  ["Other addons can ask Bastian's for any thing's name and places, your notes near a spot and your gold income through Bastians.API."] = "D'autres addons peuvent demander à Bastian's, via Bastians.API, le nom et les lieux de n'importe quoi, tes notes près d'un endroit et tes revenus en or.",
  ["When Bastian's Helpers restocks an item, it tells you if another vendor sells it cheaper and where."] = "Quand Bastian's Helpers réapprovisionne un objet, il te dit si un autre marchand le vend moins cher, et où.",
  ["What's new speaks your language: German, French, Spanish, Korean and Chinese."] = "Les nouveautés parlent ta langue : allemand, français, espagnol, coréen et chinois.",
  ["An item's price page shows a small chart of the prices your own auction house scans saw over the last two weeks."] = "La page de prix d'un objet montre une petite courbe des prix relevés par tes propres scans de l'hôtel des ventes ces deux dernières semaines.",
  ["Mail rules: tell Helpers which character gets your herbs, ore, cloth and more, and one click beside the send tab fills the mail."] = "Règles de courrier : dis à Helpers quel personnage reçoit tes herbes, minerais, tissus et plus ; un clic à côté de l'onglet d'envoi remplit le courrier.",
  ["Campfire can share your fire on a public channel and show everyone's fires (off by default, with a block list)."] = "Campfire peut partager ton feu sur un canal public et montrer les feux de tous (désactivé par défaut, avec une liste de blocage).",
  ["Bastian's Suite now speaks Russian and Brazilian Portuguese."] = "Bastian's Suite parle maintenant le russe et le portugais du Brésil.",
  ["A Gestures command can now cast, use and target: /cast and friends run as a macro when you click the wedge."] = "Une commande Gestures peut maintenant lancer un sort, utiliser et cibler : /cast et compagnie s'exécutent comme une macro quand tu cliques sur le quartier.",
  ["Other addons can now read and set Bastian's waypoint, read the account's gold and the suite's item sets through Bastians.API."] = "D'autres addons peuvent maintenant lire et poser le point de passage de Bastian's, lire l'or du compte et les ensembles d'objets de la suite via Bastians.API.",
  ["Spoken 3.8.0, the launch client's copy, is now the version the suite was tested with; the hub no longer flags it as newer."] = "Spoken 3.8.0, la version du client de lancement, compte maintenant comme testée ; le hub ne la signale plus comme plus récente.",
  ["The game's voice that reads quest texts is a woman's by default and can be chosen in the Orbiter's settings."] = "La voix du jeu qui lit les textes de quête est par défaut une voix de femme et peut être choisie dans les réglages de l'Orbiter.",
  ["Without Spoken, the Orbiter reads a quest's text with the game's own voice (Accessibility settings)."] = "Sans Spoken, l'Orbiter lit le texte d'une quête avec la voix du jeu (réglages d'accessibilité).",
  ["Bastian's Orbiter (the Voice addon, renamed): the panel keeps its place and grows around its middle, says what it plays and what a click did, has pictogram controls and its own minimap button; the game's settings pages of the suite scroll."] = "Bastian's Orbiter (l'addon Voice, renommé) : le panneau garde sa place et grandit autour de son centre, dit ce qu'il lit et ce qu'un clic a fait, a des commandes à pictogrammes et son propre bouton de mini-carte ; les pages de réglages de la suite dans le jeu défilent.",
  ["Bastian's Voice: Play on quests, zones, areas, bosses and books where Spoken has a line, the Lore Orbit around you, and quest conversations without the game's windows (off by default)."] = "Bastian's Voice : lecture pour les quêtes, zones, régions, boss et livres où Spoken a une réplique, l'Orbite des récits autour de vous, et conversations de quête sans les fenêtres du jeu (désactivé par défaut).",
  ["A note you add on a dungeon's page (or any other page) now shows on that page."] = "Une note ajoutée sur la page d'un donjon (ou de toute autre page) s'affiche désormais sur cette page.",
  ["The minimap's search finds only NPCs, quests, zones, your notes and bookmarks, and marks the place it jumps to; a quest marks its quest giver."] = "La recherche de la mini-carte ne trouve que des PNJ, des quêtes, des zones, vos notes et vos signets, et marque l'endroit où elle saute ; une quête marque son donneur de quêtes.",
  ['"Show on map" now draws what you chose (its icon and name at every place) and selects it, even when its layer is off.'] = '"Afficher sur la carte" dessine désormais ce que vous avez choisi (son icône et son nom à chaque endroit) et le sélectionne, même si sa couche est désactivée.',
  ["The map has a Dungeons and raids layer, and it switches on by itself when you pick a dungeon in the Browser."] = "La carte a une couche \"Donjons et raids\" qui s'active d'elle-même quand vous choisissez un donjon dans le Browser.",
  ["New app Bastian's Helpers: sells junk, repairs, restocks, takes all mail, helps at quest givers and shows IDs on tooltips."] = "Nouvelle application Bastian's Helpers : vend la camelote, répare, rachète les provisions, prend tout le courrier, aide auprès des donneurs de quêtes et affiche les ID dans les infobulles.",
  ["The dungeon pages name the right bosses; some showed an unrelated creature (Shadowfang Keep's first boss as Archaedas) with loot that was not its own."] = "Les pages de donjon nomment les bons boss ; certaines montraient une créature sans rapport (le premier boss du château de Griffesombre en Archaedas) avec un butin qui n'était pas le sien.",
  ["Minimap buttons close what they opened; Gestures' button opens its options; a switched-off app's button leads to its switch; a new button shows the welcome again."] = "Les boutons de la mini-carte ferment ce qu'ils ont ouvert ; le bouton de Gestes ouvre ses options ; le bouton d'une application désactivée mène à son interrupteur ; un nouveau bouton affiche de nouveau l'accueil.",
  ["Forever's own dungeons (Dalaran, the Wetlands excavation, the Hall of Thanes, the Ruins of Lordaeron) now show Santiago Reyes' hand-drawn maps with the bosses marked - thank you, Santiago!"] = "Les donjons propres à Forever (Dalaran, les fouilles des Paluns, la Salle des Thanes, les Ruines de Lordaeron) affichent désormais les cartes dessinées à la main par Santiago Reyes avec les boss marqués - merci, Santiago !",
  ["German, French and Spanish players read most quests' whole texts in their language, and the AddOn list speaks every language of the suite."] = "Les joueurs allemands, français et espagnols lisent les textes complets de la plupart des quêtes dans leur langue, et la liste des AddOns parle toutes les langues de la suite.",
  ["The game's AddOn list shows the suite as one folding \"Bastian's Suite\" header with the data packs and map styles folded under their app, in Korean and Chinese too."] = 'La liste des AddOns du jeu affiche la suite sous un seul en-tête repliable "Bastian\'s Suite", avec les packs de données et les styles de carte repliés sous leur application, y compris en coréen et en chinois.',
  ["Korean and Chinese players read the quests' whole texts in their language, and Bastian's Chat speaks French, Spanish, Korean and Chinese."] = "Les joueurs coréens et chinois lisent les textes complets des quêtes dans leur langue, et Bastian's Chat parle français, espagnol, coréen et chinois.",
  ["With Total RP 3 or MyRolePlay, Chat, Gestures and the Orbiter show other players' roleplay names."] = "Avec Total RP 3 ou MyRolePlay, Chat, Gestures et l'Orbiter affichent les noms de jeu de rôle des autres joueurs.",
  ["A new welcome: choose the Wanderer or the Scholar with a picture of your own race, set up your pack, and try your first five minutes step by step."] = "Un nouvel accueil : choisissez le Vagabond ou l'Érudit avec une image de votre propre race, configurez votre pack et essayez vos cinq premières minutes pas à pas.",
  ["Bastian's Campfire: a card while a fire is near, a camp ring in Gestures, share the fire with your group and guild, and a planner of every camp feature."] = "Bastian's Campfire : une carte lorsqu'un feu est proche, un anneau de camp dans Gestes, le feu à partager avec votre groupe et votre guilde, et un planificateur de toutes les fonctions du camp.",
  ["Emotes in Bastian's Chat now show in the colour scheme's own emote colour, for roleplay."] = "Les emotes dans Bastian's Chat s'affichent désormais dans la couleur d'emote propre au schéma de couleurs, pour le jeu de rôle.",
  ["A Gestures wedge can run one of your own macros with a click, and runs the game's own commands such as /reload; Quests' item buttons work with \"cast on key down\"."] = "Un secteur de Gestes peut lancer l'une de vos macros d'un clic et exécute les commandes du jeu comme /reload ; les boutons d'objet de Quests fonctionnent avec \"lancer à l'appui sur la touche\".",
  ["The Korean and Chinese texts of the suite read naturally and use the game's own terms."] = "Les textes coréens et chinois de la suite se lisent naturellement et emploient les termes propres au jeu.",
  ["Build your Gestures rings as you like: name them, pick any emote, your own lines, commands, the suite's and the game's controls through one filter; the wheel turns the right way; a conversation's choices no longer overlap on the Orbiter."] = "Construisez vos anneaux de Gestes comme vous voulez : nommez-les, choisissez n'importe quel emote, vos propres répliques, des commandes, les commandes de la suite et du jeu via un seul filtre ; la roue tourne dans le bon sens ; les choix d'une conversation ne se chevauchent plus sur l'Orbiter.",
  ["When someone challenges, trades or invites you, Gestures offers a bow, a wave or a polite decline; Chat's + menu has a Roleplay tab."] = "Quand quelqu'un vous défie, échange avec vous ou vous invite, Gestes propose une révérence, un salut de la main ou un refus poli ; le menu + de Chat a un onglet Jeu de rôle.",
  ["Gestures' Route home, Mark heard and Toggle the tracker wedges light up."] = 'Les secteurs "Itinéraire vers la maison", "Marquer comme entendu" et "Afficher ou masquer le suivi" de Gestes s\'illuminent désormais.',
  ["The Orbiter says when your Spoken is newer or older than the suite was tested with, never talks over Spoken or Spoken Players, and Bastian's Helpers, Chat and the Orbiter show up on broker displays; other addons can ask who knows a recipe, let the Orbiter speak, read your play preset and open any app."] = "L'Orbiter signale quand votre Spoken est plus récent ou plus ancien que la version avec laquelle la suite a été testée, ne parle jamais par-dessus Spoken ou Spoken Players, et Bastian's Helpers, Chat et l'Orbiter apparaissent sur les affichages broker ; d'autres addons peuvent demander qui connaît une recette, faire parler l'Orbiter, lire votre profil de jeu et ouvrir n'importe quelle application.",
  ["Every app wears its own mark on the minimap, in the hub, on broker displays and in the AddOns list: a compass star for the suite, a scroll for Quests, a pin for the Map, a lens for the Browser, a balance for Gold, a signpost for Route, a quill for Notes, two characters for Alts, a wrench for Helpers, bubbles for Chat, a hand for Gestures."] = "Chaque application porte sa propre marque sur la mini-carte, dans le hub, sur les affichages broker et dans la liste des AddOns : une étoile de boussole pour la suite, un parchemin pour Quests, un repère pour la carte, une loupe pour le Browser, une balance pour Gold, un panneau pour Route, une plume pour Notes, deux personnages pour Alts, une clé à molette pour Helpers, des bulles pour Chat, une main pour Gestures.",
  ["Choose how you play at the first start: the Wanderer hears Azeroth with nearly no UI, the Scholar has every quest, creature, item and place one click away; Bastian's Gestures brings emote rings and courtesy; the hub explains every app and key."] = "Choisissez dès le premier lancement votre façon de jouer : le Vagabond entend Azeroth presque sans interface, l'Érudit a chaque quête, créature, objet et lieu à un clic ; Bastian's Gestures apporte les anneaux d'emotes et la courtoisie ; le hub explique chaque application et chaque touche.",
  ["Every button shows its pictogram again and the words sit where they belong; chat tabs and buttons are easy to tell apart; the Orbiter's controls click with a creature shown, its hub drags it, and its answers are symbols; an item's page says which of your characters has it."] = "Chaque bouton affiche de nouveau son pictogramme et les mots sont à leur place ; les onglets de discussion et les boutons se distinguent facilement ; les commandes de l'Orbiter répondent au clic quand une créature est affichée, son hub le déplace et ses réponses sont des symboles ; la page d'un objet indique lequel de vos personnages le possède.",
  ["Trainers say what they train on the map and on their page, and their list of spells shows who of your characters knows each one; item lists filter by who owns an item; the Orbiter hides with the clear-screen key and drags by its hub; the Browser's hover preview is a setting."] = "Les entraîneurs indiquent ce qu'ils enseignent sur la carte et sur leur page, et leur liste de sorts montre lequel de vos personnages connaît chacun ; les listes d'objets se filtrent selon le propriétaire ; l'Orbiter se masque avec la touche d'effacement de l'écran et se déplace par son hub ; l'aperçu au survol du Browser est un réglage.",
  ["Every app offers a data-broker feed (Titan, Bazooka, ElvUI and the like), the Addon Compartment lists the suite, bag addons get the suite's item sets, and other addons can read the suite through Bastians.API."] = "Chaque application propose un flux data-broker (Titan, Bazooka, ElvUI et autres), le compartiment des addons liste la suite, les addons de sacs reçoivent les ensembles d'objets de la suite, et d'autres addons peuvent lire la suite via Bastians.API.",
  ["The Orbiter's bubbles glide to their places and the one that plays is coloured; Show on map always draws what you chose; the junk filter also cleans the lines already on screen; the game's voice is found once the client lists it."] = "Les bulles de l'Orbiter glissent à leur place et celle qui est lue est colorée ; \"Afficher sur la carte\" dessine toujours ce que vous avez choisi ; le filtre de camelote nettoie aussi les lignes déjà à l'écran ; la voix du jeu est trouvée dès que le client la liste.",
  ["Seven looks to pick from, including Night, Glass and Parchment; every button of the suite shows a pictogram; every colour scheme is checked for readable text."] = "Sept apparences au choix, dont Nuit, Verre et Parchemin ; chaque bouton de la suite affiche un pictogramme ; chaque schéma de couleurs est vérifié pour un texte lisible.",
  ["the Browser's filter pills use the pane's width and the first row is never hidden, the Mobs search works again, zones appear once, a preview needs Shift, and a note saved on a page shows at once."] = "Les pastilles de filtre du Browser utilisent la largeur du panneau et la première ligne n'est jamais masquée, la recherche de monstres fonctionne de nouveau, les zones n'apparaissent qu'une fois, un aperçu demande Shift, et une note enregistrée sur une page s'affiche aussitôt.",
  ['one search syntax in every box (words, "phrases", OR, -not, field:value, level>30), the text keys Ctrl+Backspace/Delete/Left/Right, a key that clears the screen for role play, a lock on every window, and the new look engine behind Modern and WoW.'] = "Une seule syntaxe de recherche dans chaque champ (mots, \"phrases\", OR, -not, field:value, level>30), les touches de texte Ctrl+Backspace/Delete/Left/Right, une touche qui efface l'écran pour le jeu de rôle, un verrou sur chaque fenêtre et le nouveau moteur d'apparence derrière Moderne et WoW.",
  ['Bastian\'s Helpers also writes its notices into a chat tab named "Addons" when you have one.'] = 'Bastian\'s Helpers écrit aussi ses notifications dans un onglet de discussion nommé "Addons" si vous en avez un.',
  ['The colour picker opens in front of the settings, and no "blocked" message appears in combat.'] = "Le sélecteur de couleurs s'ouvre devant les réglages, et aucun message \"bloqué\" n'apparaît en combat.",
  ["The map's layer bar names each icon the moment you point at it."] = "La barre des couches de la carte nomme chaque icône dès que vous la pointez.",
  ["Other addons can ask Bastian's for prices, quest state, the active route and travel times, start a route, and listen to its events through Bastians.API."] = "D'autres addons peuvent demander à Bastian's les prix, l'état des quêtes, l'itinéraire actif et les temps de trajet, lancer un itinéraire et écouter ses événements via Bastians.API.",
  ["Wide buttons in the WoW look keep the game's rounded ends instead of stretching them."] = "Les larges boutons à l'apparence WoW gardent les extrémités arrondies du jeu au lieu de les étirer.",
  ["Bastian's apps show in Titan Panel, Bazooka, EllesmereUI's data bars and every other LibDataBroker display, in the addon compartment, and sort your bags in BetterBags, Baganator and AdiBags."] = "Les applications de Bastian's apparaissent dans Titan Panel, Bazooka, les barres de données d'EllesmereUI et tout autre affichage LibDataBroker, dans le compartiment des addons, et trient vos sacs dans BetterBags, Baganator et AdiBags.",
  ["Bastian's Chat gets a live tab filter, tab windows that dock back, a Messenger of the WhatsApp kind with class icons and a search, and a lock on every chat window."] = "Bastian's Chat reçoit un filtre d'onglets en direct, des fenêtres d'onglet qui se réamarrent, un Messenger façon WhatsApp avec icônes de classe et une recherche, et un verrou sur chaque fenêtre de discussion.",
  ["All %d"] = "Les %d",
  ["Step inside"] = "Entrer",
  -- UI/Dossier.lua: tabs inside a sheet, facts as tiles (ADR 0058, 07.11.2026)
  ["Overview"] = "Aperçu",
  ["unknown"] = "inconnu",
})
